with genre_counts as (select customer.customerid, customer.firstname, customer.lastname, genre.name as genre_name, row_number() over (partition by customer.customerid order by sum(coalesce(invoiceline.quantity, 1)) desc, genre.name asc) as rn from customer left join invoice on customer.customerid = invoice.customerid left join invoiceline on invoice.invoiceid = invoiceline.invoiceid left join track on invoiceline.trackid = track.trackid left join genre on track.genreid = genre.genreid where genre.name is not null group by customer.customerid, customer.firstname, customer.lastname, genre.genreid, genre.name) select firstname, lastname, genre_name from genre_counts where rn = 1 order by firstname asc, lastname asc;
